import { writeFileSync, mkdirSync } from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const __dirname = path.dirname(fileURLToPath(import.meta.url));
const evalDir = path.resolve(__dirname, "../eval");
mkdirSync(evalDir, { recursive: true });

const baseProblems = [
  // Arrays & Hashing (15)
  { title: "Two Sum Indices", category: "arrays", difficulty: "Introductory", statement: "Given an array of integers nums and an integer target, print the 0-based indices of the two numbers that add up to target, space-separated.", starterPy: "import sys\n# Read n, target, and array\n", solPy: "import sys\ndata=sys.stdin.read().split()\nif data:\n n,t=int(data[0]),int(data[1])\n a=[int(x) for x in data[2:2+n]]\n m={}\n for i,x in enumerate(a):\n  if t-x in m:\n   print(f'{m[t-x]} {i}');break\n  m[x]=i", sample: [{ stdin: "4 9\n2 7 11 15", expectedOutput: "0 1" }], hidden: [{ stdin: "3 6\n3 2 4", expectedOutput: "1 2" }, { stdin: "2 6\n3 3", expectedOutput: "0 1" }], complexity: "O(n)", conceptTags: ["hash-map", "arrays"] },
  { title: "Maximum Subarray Sum (Kadane)", category: "arrays", difficulty: "Intermediate", statement: "Given N integers, print the maximum contiguous subarray sum.", starterPy: "import sys\n", solPy: "import sys\ndata=[int(x) for x in sys.stdin.read().split()]\nif data:\n n=data[0];a=data[1:1+n]\n cur=best=a[0]\n for x in a[1:]:\n  cur=max(x,cur+x);best=max(best,cur)\n print(best)", sample: [{ stdin: "5\n-2 1 -3 4 -1", expectedOutput: "4" }], hidden: [{ stdin: "4\n1 2 3 4", expectedOutput: "10" }, { stdin: "3\n-5 -2 -9", expectedOutput: "-2" }], complexity: "O(n)", conceptTags: ["dp", "kadane", "arrays"] },
  { title: "Contains Duplicate", category: "arrays", difficulty: "Introductory", statement: "Given N integers, print TRUE if any value appears at least twice, else FALSE.", starterPy: "import sys\n", solPy: "import sys\nd=[int(x) for x in sys.stdin.read().split()]\nif d:\n a=d[1:1+d[0]]\n print('TRUE' if len(a)!=len(set(a)) else 'FALSE')", sample: [{ stdin: "4\n1 2 3 1", expectedOutput: "TRUE" }], hidden: [{ stdin: "4\n1 2 3 4", expectedOutput: "FALSE" }], complexity: "O(n)", conceptTags: ["hash-set", "arrays"] },
  { title: "Product of Array Except Self", category: "arrays", difficulty: "Intermediate", statement: "Given N integers, print space-separated products of all elements except self without division.", starterPy: "import sys\n", solPy: "import sys\nd=[int(x) for x in sys.stdin.read().split()]\nif d:\n n=d[0];a=d[1:1+n];res=[1]*n;p=1\n for i in range(n): res[i]=p;p*=a[i]\n s=1\n for i in range(n-1,-1,-1): res[i]*=s;s*=a[i]\n print(' '.join(map(str,res)))", sample: [{ stdin: "4\n1 2 3 4", expectedOutput: "24 12 8 6" }], hidden: [{ stdin: "3\n2 3 4", expectedOutput: "12 8 6" }, { stdin: "4\n-1 1 0 -3", expectedOutput: "0 0 3 0" }], complexity: "O(n)", conceptTags: ["prefix-sum", "arrays"] },
  { title: "Rotate Array Right by K", category: "arrays", difficulty: "Introductory", statement: "Rotate an array of N integers to the right by K steps and print space-separated.", starterPy: "import sys\n", solPy: "import sys\nd=[int(x) for x in sys.stdin.read().split()]\nif d:\n n,k=d[0],d[1];a=d[2:2+n];k%=n\n r=a[-k:]+a[:-k] if k else a\n print(' '.join(map(str,r)))", sample: [{ stdin: "5 2\n1 2 3 4 5", expectedOutput: "4 5 1 2 3" }], hidden: [{ stdin: "4 4\n10 20 30 40", expectedOutput: "10 20 30 40" }], complexity: "O(n)", conceptTags: ["arrays", "two-pointers"] },
  { title: "Move Zeroes to End", category: "arrays", difficulty: "Introductory", statement: "Move all 0s to the end of the array while maintaining relative order of non-zero elements.", starterPy: "import sys\n", solPy: "import sys\nd=[int(x) for x in sys.stdin.read().split()]\nif d:\n n=d[0];a=d[1:1+n]\n nz=[x for x in a if x!=0]+[0]*a.count(0)\n print(' '.join(map(str,nz)))", sample: [{ stdin: "5\n0 1 0 3 12", expectedOutput: "1 3 12 0 0" }], hidden: [{ stdin: "3\n0 0 1", expectedOutput: "1 0 0" }], complexity: "O(n)", conceptTags: ["two-pointers", "arrays"] },
  { title: "Find Missing Number 0..N", category: "arrays", difficulty: "Introductory", statement: "Given N distinct numbers taken from 0, 1, 2, ..., N, print the missing number.", starterPy: "import sys\n", solPy: "import sys\nd=[int(x) for x in sys.stdin.read().split()]\nif d:\n n=d[0];a=d[1:1+n]\n print(n*(n+1)//2 - sum(a))", sample: [{ stdin: "3\n3 0 1", expectedOutput: "2" }], hidden: [{ stdin: "2\n0 1", expectedOutput: "2" }], complexity: "O(n)", conceptTags: ["math", "bit-manipulation"] },
  { title: "Majority Element (> N/2)", category: "arrays", difficulty: "Introductory", statement: "Find the element that appears more than floor(N/2) times using Boyer-Moore voting.", starterPy: "import sys\n", solPy: "import sys\nd=[int(x) for x in sys.stdin.read().split()]\nif d:\n a=d[1:1+d[0]];c=0;cand=None\n for x in a:\n  if c==0: cand=x\n  c+=(1 if x==cand else -1)\n print(cand)", sample: [{ stdin: "7\n2 2 1 1 1 2 2", expectedOutput: "2" }], hidden: [{ stdin: "3\n3 2 3", expectedOutput: "3" }], complexity: "O(n)", conceptTags: ["arrays", "voting"] },
  { title: "Merge Overlapping Intervals Count", category: "arrays", difficulty: "Intermediate", statement: "Given N intervals [s, e], merge overlapping intervals and print the count of merged intervals.", starterPy: "import sys\n", solPy: "import sys\nd=[int(x) for x in sys.stdin.read().split()]\nif d:\n n=d[0];iv=sorted([(d[1+2*i],d[2+2*i]) for i in range(n)])\n m=[list(iv[0])]\n for s,e in iv[1:]:\n  if s<=m[-1][1]: m[-1][1]=max(m[-1][1],e)\n  else: m.append([s,e])\n print(len(m))", sample: [{ stdin: "4\n1 3 2 6 8 10 15 18", expectedOutput: "3" }], hidden: [{ stdin: "2\n1 4 4 5", expectedOutput: "1" }], complexity: "O(n log n)", conceptTags: ["intervals", "sorting"] },
  { title: "Subarray Sum Equals K Count", category: "arrays", difficulty: "Intermediate", statement: "Given N integers and target K, print the total number of contiguous subarrays whose sum equals K.", starterPy: "import sys\n", solPy: "import sys\nd=[int(x) for x in sys.stdin.read().split()]\nif d:\n n,k=d[0],d[1];a=d[2:2+n];cnt={0:1};s=ans=0\n for x in a:\n  s+=x;ans+=cnt.get(s-k,0);cnt[s]=cnt.get(s,0)+1\n print(ans)", sample: [{ stdin: "3 2\n1 1 1", expectedOutput: "2" }], hidden: [{ stdin: "3 3\n1 2 3", expectedOutput: "2" }], complexity: "O(n)", conceptTags: ["prefix-sum", "hash-map"] },
  { title: "Trapping Rain Water", category: "arrays", difficulty: "Advanced", statement: "Given N non-negative integers representing elevation map bar heights of width 1, compute how much water it can trap after raining.", starterPy: "import sys\n", solPy: "import sys\nd=[int(x) for x in sys.stdin.read().split()]\nif d:\n n=d[0];h=d[1:1+n];l,r=0,n-1;lm=rm=ans=0\n while l<=r:\n  if h[l]<=h[r]:\n   lm=max(lm,h[l]);ans+=lm-h[l];l+=1\n  else:\n   rm=max(rm,h[r]);ans+=rm-h[r];r-=1\n print(ans)", sample: [{ stdin: "12\n0 1 0 2 1 0 1 3 2 1 2 1", expectedOutput: "6" }], hidden: [{ stdin: "6\n4 2 0 3 2 5", expectedOutput: "9" }], complexity: "O(n)", conceptTags: ["two-pointers", "arrays"] },
  { title: "Sliding Window Maximum Sum of Size K", category: "arrays", difficulty: "Introductory", statement: "Given N integers and window size K, print the maximum sum of any contiguous subarray of length K.", starterPy: "import sys\n", solPy: "import sys\nd=[int(x) for x in sys.stdin.read().split()]\nif d:\n n,k=d[0],d[1];a=d[2:2+n];cur=best=sum(a[:k])\n for i in range(k,n):\n  cur+=a[i]-a[i-k];best=max(best,cur)\n print(best)", sample: [{ stdin: "5 3\n2 1 5 1 3", expectedOutput: "9" }], hidden: [{ stdin: "4 2\n10 20 30 40", expectedOutput: "70" }], complexity: "O(n)", conceptTags: ["sliding-window", "arrays"] },
  { title: "Largest Rectangle in Histogram", category: "arrays", difficulty: "Advanced", statement: "Given N bar heights in a histogram where each bar has width 1, print the area of the largest rectangle.", starterPy: "import sys\n", solPy: "import sys\nd=[int(x) for x in sys.stdin.read().split()]\nif d:\n n=d[0];h=d[1:1+n]+[0];st=[];best=0\n for i,x in enumerate(h):\n  while st and h[st[-1]]>=x:\n   ht=h[st.pop()];w=i if not st else i-st[-1]-1;best=max(best,ht*w)\n  st.append(i)\n print(best)", sample: [{ stdin: "6\n2 1 5 6 2 3", expectedOutput: "10" }], hidden: [{ stdin: "2\n2 4", expectedOutput: "4" }], complexity: "O(n)", conceptTags: ["monotonic-stack", "arrays"] },
  { title: "Median of Two Sorted Arrays (Merged Double)", category: "arrays", difficulty: "Advanced", statement: "Given two sorted arrays of sizes M and N, print twice the median (i.e. 2 * median as an integer) so output is always an integer.", starterPy: "import sys\n", solPy: "import sys\nd=[int(x) for x in sys.stdin.read().split()]\nif d:\n m,n=d[0],d[1];a=sorted(d[2:2+m+n]);k=m+n\n print(a[k//2]*2 if k%2 else a[k//2-1]+a[k//2])", sample: [{ stdin: "2 1\n1 3\n2", expectedOutput: "4" }], hidden: [{ stdin: "2 2\n1 2\n3 4", expectedOutput: "5" }], complexity: "O(log(min(m,n)))", conceptTags: ["binary-search", "arrays"] },
  { title: "Next Greater Element Circular", category: "arrays", difficulty: "Intermediate", statement: "Given N integers in a circular array, print space-separated next greater element for each index (-1 if none).", starterPy: "import sys\n", solPy: "import sys\nd=[int(x) for x in sys.stdin.read().split()]\nif d:\n n=d[0];a=d[1:1+n];res=[-1]*n;st=[]\n for i in range(2*n):\n  while st and a[st[-1]]<a[i%n]: res[st.pop()]=a[i%n]\n  if i<n: st.append(i)\n print(' '.join(map(str,res)))", sample: [{ stdin: "3\n1 2 1", expectedOutput: "2 -1 2" }], hidden: [{ stdin: "4\n4 3 2 1", expectedOutput: "-1 4 4 4" }], complexity: "O(n)", conceptTags: ["monotonic-stack", "arrays"] },

  // Strings (14)
  { title: "Valid Palindrome Alphanumeric", category: "strings", difficulty: "Introductory", statement: "Given a string, print YES if it is a palindrome considering only alphanumeric characters and ignoring cases, else NO.", starterPy: "import sys\n", solPy: "import sys\ns=''.join(c.lower() for c in sys.stdin.read() if c.isalnum())\nprint('YES' if s==s[::-1] else 'NO')", sample: [{ stdin: "A man, a plan, a canal: Panama", expectedOutput: "YES" }], hidden: [{ stdin: "race a car", expectedOutput: "NO" }], complexity: "O(n)", conceptTags: ["two-pointers", "strings"] },
  { title: "Valid Anagram Check", category: "strings", difficulty: "Introductory", statement: "Given two whitespace-separated strings s and t, print YES if t is an anagram of s, else NO.", starterPy: "import sys\n", solPy: "import sys\np=sys.stdin.read().split()\nif len(p)>=2: print('YES' if sorted(p[0])==sorted(p[1]) else 'NO')", sample: [{ stdin: "listen silent", expectedOutput: "YES" }], hidden: [{ stdin: "rat car", expectedOutput: "NO" }], complexity: "O(n log n)", conceptTags: ["strings", "sorting"] },
  { title: "Longest Substring Without Repeating Characters", category: "strings", difficulty: "Intermediate", statement: "Given a string s, print the length of the longest substring without repeating characters.", starterPy: "import sys\n", solPy: "import sys\ns=sys.stdin.read().strip()\nseen={};l=best=0\nfor r,c in enumerate(s):\n if c in seen and seen[c]>=l: l=seen[c]+1\n seen[c]=r;best=max(best,r-l+1)\nprint(best)", sample: [{ stdin: "abcabcbb", expectedOutput: "3" }], hidden: [{ stdin: "bbbbb", expectedOutput: "1" }, { stdin: "pwwkew", expectedOutput: "3" }], complexity: "O(n)", conceptTags: ["sliding-window", "strings"] },
  { title: "Balanced Brackets Validator", category: "strings", difficulty: "Introductory", statement: "Given a bracket string containing (), {}, [], print VALID if balanced, else INVALID.", starterPy: "import sys\n", solPy: "import sys\ns=sys.stdin.read().strip();st=[];mp={')':'(','}':'{',']':'['};ok=True\nfor c in s:\n if c in '({[': st.append(c)\n elif c in mp:\n  if not st or st.pop()!=mp[c]: ok=False;break\nprint('VALID' if ok and not st else 'INVALID')", sample: [{ stdin: "()[]{}", expectedOutput: "VALID" }], hidden: [{ stdin: "([)]", expectedOutput: "INVALID" }], complexity: "O(n)", conceptTags: ["stack", "strings"] },
  { title: "First Non-Repeating Character Index", category: "strings", difficulty: "Introductory", statement: "Given a lowercase string, print the 0-based index of its first non-repeating character, or -1 if none.", starterPy: "import sys\n", solPy: "import sys\nfrom collections import Counter\ns=sys.stdin.read().strip();c=Counter(s)\nans=-1\nfor i,ch in enumerate(s):\n if c[ch]==1: ans=i;break\nprint(ans)", sample: [{ stdin: "leetcode", expectedOutput: "0" }], hidden: [{ stdin: "aabb", expectedOutput: "-1" }], complexity: "O(n)", conceptTags: ["hash-map", "strings"] },
  { title: "Run-Length Encoding Count", category: "strings", difficulty: "Introductory", statement: "Compress string s as char+count (e.g., aaabb -> a3b2) and print the compressed string.", starterPy: "import sys\n", solPy: "import sys\ns=sys.stdin.read().strip()\nif not s: print('')\nelse:\n out=[];cur=s[0];cnt=1\n for c in s[1:]:\n  if c==cur: cnt+=1\n  else: out.append(f'{cur}{cnt}');cur=c;cnt=1\n out.append(f'{cur}{cnt}')\n print(''.join(out))", sample: [{ stdin: "aaabbc", expectedOutput: "a3b2c1" }], hidden: [{ stdin: "xxxx", expectedOutput: "x4" }], complexity: "O(n)", conceptTags: ["strings"] },
  { title: "Reverse Words in Sentence", category: "strings", difficulty: "Introductory", statement: "Reverse the order of whitespace-separated words in the input line.", starterPy: "import sys\n", solPy: "import sys\nw=sys.stdin.read().split()\nprint(' '.join(reversed(w)))", sample: [{ stdin: "the sky is blue", expectedOutput: "blue is sky the" }], hidden: [{ stdin: "hello world", expectedOutput: "world hello" }], complexity: "O(n)", conceptTags: ["strings"] },
  { title: "Longest Common Prefix", category: "strings", difficulty: "Introductory", statement: "Given N words, print their longest common prefix or EMPTY if none.", starterPy: "import sys\n", solPy: "import sys\nw=sys.stdin.read().split()\nif w:\n n=int(w[0]);arr=w[1:1+n];p=arr[0]\n for s in arr[1:]:\n  while not s.startswith(p): p=p[:-1]\n print(p if p else 'EMPTY')", sample: [{ stdin: "3 flower flow flight", expectedOutput: "fl" }], hidden: [{ stdin: "2 dog racecar", expectedOutput: "EMPTY" }], complexity: "O(S)", conceptTags: ["strings", "trie"] },
  { title: "Edit Distance (Levenshtein)", category: "strings", difficulty: "Advanced", statement: "Given two strings s1 and s2, print the minimum number of operations (insert, delete, replace) to convert s1 to s2.", starterPy: "import sys\n", solPy: "import sys\nw=sys.stdin.read().split()\nif len(w)>=2:\n a,b=w[0],w[1];m,n=len(a),len(b)\n dp=[[0]*(n+1) for _ in range(m+1)]\n for i in range(m+1): dp[i][0]=i\n for j in range(n+1): dp[0][j]=j\n for i in range(1,m+1):\n  for j in range(1,n+1):\n   dp[i][j]=dp[i-1][j-1] if a[i-1]==b[j-1] else 1+min(dp[i-1][j],dp[i][j-1],dp[i-1][j-1])\n print(dp[m][n])", sample: [{ stdin: "horse ros", expectedOutput: "3" }], hidden: [{ stdin: "intention execution", expectedOutput: "5" }], complexity: "O(m*n)", conceptTags: ["dp", "strings"] },
  { title: "KMP Pattern Occurrences Count", category: "strings", difficulty: "Intermediate", statement: "Given text T and pattern P, print how many times P occurs in T (including overlapping).", starterPy: "import sys\n", solPy: "import sys\nw=sys.stdin.read().split()\nif len(w)>=2:\n t,p=w[0],w[1];c=0\n for i in range(len(t)-len(p)+1):\n  if t[i:i+len(p)]==p: c+=1\n print(c)", sample: [{ stdin: "aaaaa aa", expectedOutput: "4" }], hidden: [{ stdin: "abababa aba", expectedOutput: "3" }], complexity: "O(n)", conceptTags: ["kmp", "strings"] },
  { title: "Minimum Window Substring Length", category: "strings", difficulty: "Advanced", statement: "Given strings S and T, print the length of the minimum window substring of S that contains all characters of T (with multiplicity), or 0 if none.", starterPy: "import sys\n", solPy: "import sys\nfrom collections import Counter\nw=sys.stdin.read().split()\nif len(w)>=2:\n s,t=w[0],w[1];need=Counter(t);missing=len(t);l=0;best=len(s)+1\n for r,ch in enumerate(s):\n  if need[ch]>0: missing-=1\n  need[ch]-=1\n  while missing==0:\n   best=min(best,r-l+1);need[s[l]]+=1\n   if need[s[l]]>0: missing+=1\n   l+=1\n print(0 if best>len(s) else best)", sample: [{ stdin: "ADOBECODEBANC ABC", expectedOutput: "4" }], hidden: [{ stdin: "a aa", expectedOutput: "0" }], complexity: "O(n)", conceptTags: ["sliding-window", "strings"] },
  { title: "Longest Palindromic Substring Length", category: "strings", difficulty: "Intermediate", statement: "Given string S, print the length of its longest palindromic substring.", starterPy: "import sys\n", solPy: "import sys\ns=sys.stdin.read().strip();best=0\nfor i in range(len(s)):\n for l,r in ((i,i),(i,i+1)):\n  while l>=0 and r<len(s) and s[l]==s[r]: best=max(best,r-l+1);l-=1;r+=1\nprint(best)", sample: [{ stdin: "babad", expectedOutput: "3" }], hidden: [{ stdin: "cbbd", expectedOutput: "2" }], complexity: "O(n^2)", conceptTags: ["two-pointers", "strings"] },
  { title: "Z-Algorithm Prefix Match Sum", category: "strings", difficulty: "Advanced", statement: "Given string S, compute the sum of lengths of longest common prefix between S and each suffix of S (including S itself).", starterPy: "import sys\n", solPy: "import sys\ns=sys.stdin.read().strip();n=len(s);tot=0\nfor i in range(n):\n k=0\n while i+k<n and s[k]==s[i+k]: k+=1\n tot+=k\nprint(tot)", sample: [{ stdin: "ababaa", expectedOutput: "11" }], hidden: [{ stdin: "aaaa", expectedOutput: "10" }], complexity: "O(n)", conceptTags: ["z-algorithm", "strings"] },
  { title: "Rabin-Karp Distinct Substrings of Length K", category: "strings", difficulty: "Intermediate", statement: "Given string S and integer K, print the number of distinct substrings of length K.", starterPy: "import sys\n", solPy: "import sys\nw=sys.stdin.read().split()\nif len(w)>=2:\n s,k=w[0],int(w[1])\n print(len({s[i:i+k] for i in range(len(s)-k+1)}) if k<=len(s) else 0)", sample: [{ stdin: "ababa 2", expectedOutput: "2" }], hidden: [{ stdin: "aaaa 2", expectedOutput: "1" }], complexity: "O(n)", conceptTags: ["rolling-hash", "strings"] },

  // Dynamic Programming (14)
  { title: "Climbing Stairs Ways", category: "dp", difficulty: "Introductory", statement: "Given N stairs where you can climb 1 or 2 steps at a time, print the number of distinct ways to reach the top.", starterPy: "import sys\n", solPy: "import sys\nn=int(sys.stdin.read().strip() or 0)\na,b=1,1\nfor _ in range(n): a,b=b,a+b\nprint(a)", sample: [{ stdin: "3", expectedOutput: "3" }], hidden: [{ stdin: "5", expectedOutput: "8" }], complexity: "O(n)", conceptTags: ["dp"] },
  { title: "Coin Change Minimum Coins", category: "dp", difficulty: "Intermediate", statement: "Given N coin denominations, target amount A, and the coins, print minimum coins needed to make A, or -1 if impossible.", starterPy: "import sys\n", solPy: "import sys\nd=[int(x) for x in sys.stdin.read().split()]\nif d:\n n,amt=d[0],d[1];c=d[2:2+n];dp=[amt+1]*(amt+1);dp[0]=0\n for x in range(1,amt+1):\n  for coin in c:\n   if x>=coin: dp[x]=min(dp[x],dp[x-coin]+1)\n print(dp[amt] if dp[amt]<=amt else -1)", sample: [{ stdin: "3 11\n1 2 5", expectedOutput: "3" }], hidden: [{ stdin: "1 3\n2", expectedOutput: "-1" }], complexity: "O(n*A)", conceptTags: ["dp"] },
  { title: "Longest Increasing Subsequence Length", category: "dp", difficulty: "Intermediate", statement: "Given N integers, print the length of the longest strictly increasing subsequence.", starterPy: "import sys\n", solPy: "import sys,bisect\nd=[int(x) for x in sys.stdin.read().split()]\nif d:\n a=d[1:1+d[0]];tails=[]\n for x in a:\n  i=bisect.bisect_left(tails,x)\n  if i==len(tails): tails.append(x)\n  else: tails[i]=x\n print(len(tails))", sample: [{ stdin: "8\n10 9 2 5 3 7 101 18", expectedOutput: "4" }], hidden: [{ stdin: "6\n0 1 0 3 2 3", expectedOutput: "4" }], complexity: "O(n log n)", conceptTags: ["dp", "binary-search"] },
  { title: "0/1 Knapsack Maximum Value", category: "dp", difficulty: "Intermediate", statement: "Given N items, capacity W, followed by N pairs of (weight, value), print maximum value achievable.", starterPy: "import sys\n", solPy: "import sys\nd=[int(x) for x in sys.stdin.read().split()]\nif d:\n n,w=d[0],d[1];dp=[0]*(w+1)\n for i in range(n):\n  wt,val=d[2+2*i],d[3+2*i]\n  for c in range(w,wt-1,-1): dp[c]=max(dp[c],dp[c-wt]+val)\n print(dp[w])", sample: [{ stdin: "3 50\n10 60 20 100 30 120", expectedOutput: "220" }], hidden: [{ stdin: "2 3\n4 5 5 6", expectedOutput: "0" }], complexity: "O(n*W)", conceptTags: ["dp", "knapsack"] },
  { title: "House Robber Maximum Non-Adjacent Sum", category: "dp", difficulty: "Intermediate", statement: "Given N non-negative integers representing money in houses, print maximum amount you can rob without robbing adjacent houses.", starterPy: "import sys\n", solPy: "import sys\nd=[int(x) for x in sys.stdin.read().split()]\nif d:\n a=d[1:1+d[0]];p1=p2=0\n for x in a: p1,p2=max(p1,p2+x),p1\n print(p1)", sample: [{ stdin: "4\n1 2 3 1", expectedOutput: "4" }], hidden: [{ stdin: "5\n2 7 9 3 1", expectedOutput: "12" }], complexity: "O(n)", conceptTags: ["dp"] },
  { title: "Longest Common Subsequence Length", category: "dp", difficulty: "Intermediate", statement: "Given two strings s1 and s2, print the length of their longest common subsequence.", starterPy: "import sys\n", solPy: "import sys\nw=sys.stdin.read().split()\nif len(w)>=2:\n a,b=w[0],w[1];dp=[0]*(len(b)+1)\n for ca in a:\n  prev=0\n  for j,cb in enumerate(b,1):\n   tmp=dp[j]\n   dp[j]=prev+1 if ca==cb else max(dp[j],dp[j-1])\n   prev=tmp\n print(dp[-1])", sample: [{ stdin: "abcde ace", expectedOutput: "3" }], hidden: [{ stdin: "abc def", expectedOutput: "0" }], complexity: "O(m*n)", conceptTags: ["dp", "strings"] },
  { title: "Unique Grid Paths (M x N)", category: "dp", difficulty: "Introductory", statement: "Given grid dimensions M and N, print the number of unique paths from top-left to bottom-right moving only right or down.", starterPy: "import sys\n", solPy: "import sys,math\nd=[int(x) for x in sys.stdin.read().split()]\nif len(d)>=2: m,n=d[0],d[1];print(math.comb(m+n-2,m-1))", sample: [{ stdin: "3 7", expectedOutput: "28" }], hidden: [{ stdin: "3 2", expectedOutput: "3" }], complexity: "O(min(m,n))", conceptTags: ["dp", "combinatorics"] },
  { title: "Minimum Path Sum in Grid", category: "dp", difficulty: "Intermediate", statement: "Given M, N and M*N non-negative integers, find minimum path sum from top-left to bottom-right.", starterPy: "import sys\n", solPy: "import sys\nd=[int(x) for x in sys.stdin.read().split()]\nif d:\n m,n=d[0],d[1];g=[d[2+i*n:2+(i+1)*n] for i in range(m)]\n for i in range(m):\n  for j in range(n):\n   if i and j: g[i][j]+=min(g[i-1][j],g[i][j-1])\n   elif i: g[i][j]+=g[i-1][j]\n   elif j: g[i][j]+=g[i][j-1]\n print(g[-1][-1])", sample: [{ stdin: "3 3\n1 3 1 1 5 1 4 2 1", expectedOutput: "7" }], hidden: [{ stdin: "2 3\n1 2 3 4 5 6", expectedOutput: "12" }], complexity: "O(m*n)", conceptTags: ["dp", "grid"] },
  { title: "Partition Equal Subset Sum", category: "dp", difficulty: "Intermediate", statement: "Given N positive integers, print YES if the array can be partitioned into two subsets with equal sum, else NO.", starterPy: "import sys\n", solPy: "import sys\nd=[int(x) for x in sys.stdin.read().split()]\nif d:\n a=d[1:1+d[0]];s=sum(a)\n if s%2: print('NO')\n else:\n  t=s//2;dp={0}\n  for x in a: dp|={v+x for v in dp if v+x<=t}\n  print('YES' if t in dp else 'NO')", sample: [{ stdin: "4\n1 5 11 5", expectedOutput: "YES" }], hidden: [{ stdin: "4\n1 2 3 5", expectedOutput: "NO" }], complexity: "O(n*sum)", conceptTags: ["dp", "subset-sum"] },
  { title: "Nth Tribonacci Number", category: "dp", difficulty: "Introductory", statement: "Given N (T0=0, T1=1, T2=1, Tn=Tn-1+Tn-2+Tn-3), print Tn.", starterPy: "import sys\n", solPy: "import sys\nn=int(sys.stdin.read().strip() or 0)\na,b,c=0,1,1\nfor _ in range(n): a,b,c=b,c,a+b+c\nprint(a)", sample: [{ stdin: "4", expectedOutput: "4" }], hidden: [{ stdin: "25", expectedOutput: "1389537" }], complexity: "O(n)", conceptTags: ["dp"] },
  { title: "Matrix Chain Multiplication Minimum Cost", category: "dp", difficulty: "Advanced", statement: "Given N+1 dimensions for N matrices, print the minimum number of scalar multiplications needed to multiply the chain.", starterPy: "import sys\n", solPy: "import sys\nd=[int(x) for x in sys.stdin.read().split()]\nif d:\n m=d[0];p=d[1:1+m];n=len(p)-1;dp=[[0]*n for _ in range(n)]\n for l in range(2,n+1):\n  for i in range(n-l+1):\n   j=i+l-1;dp[i][j]=min(dp[i][k]+dp[k+1][j]+p[i]*p[k+1]*p[j+1] for k in range(i,j))\n print(dp[0][-1])", sample: [{ stdin: "4\n10 30 5 60", expectedOutput: "4500" }], hidden: [{ stdin: "5\n40 20 30 10 30", expectedOutput: "26000" }], complexity: "O(n^3)", conceptTags: ["interval-dp", "dp"] },
  { title: "Burst Balloons Maximum Coins", category: "dp", difficulty: "Advanced", statement: "Given N balloons with values, bursting balloon i yields nums[left]*nums[i]*nums[right] coins (boundaries are 1). Print max coins.", starterPy: "import sys\n", solPy: "import sys\nd=[int(x) for x in sys.stdin.read().split()]\nif d:\n n=d[0];a=[1]+d[1:1+n]+[1];m=len(a);dp=[[0]*m for _ in range(m)]\n for l in range(2,m):\n  for i in range(m-l):\n   j=i+l;dp[i][j]=max(dp[i][k]+dp[k][j]+a[i]*a[k]*a[j] for k in range(i+1,j))\n print(dp[0][-1])", sample: [{ stdin: "4\n3 1 5 8", expectedOutput: "167" }], hidden: [{ stdin: "2\n1 5", expectedOutput: "10" }], complexity: "O(n^3)", conceptTags: ["interval-dp", "dp"] },
  { title: "Egg Dropping Minimum Trials (K Eggs, N Floors)", category: "dp", difficulty: "Advanced", statement: "Given K eggs and N floors, print minimum trials needed in worst case to find the critical floor.", starterPy: "import sys\n", solPy: "import sys\nd=[int(x) for x in sys.stdin.read().split()]\nif len(d)>=2:\n k,n=d[0],d[1];dp=[0]*(k+1);m=0\n while dp[k]<n:\n  m+=1\n  for i in range(k,0,-1): dp[i]+=dp[i-1]+1\n print(m)", sample: [{ stdin: "2 6", expectedOutput: "3" }], hidden: [{ stdin: "3 14", expectedOutput: "4" }], complexity: "O(K log N)", conceptTags: ["dp", "math"] },
  { title: "Travelling Salesman Tour Bitmask DP", category: "dp", difficulty: "Advanced", statement: "Given N cities and N*N distance matrix, print minimum cost tour starting and ending at city 0 visiting all cities.", starterPy: "import sys\n", solPy: "import sys\nd=[int(x) for x in sys.stdin.read().split()]\nif d:\n n=d[0];g=[d[1+i*n:1+(i+1)*n] for i in range(n)];INF=10**15\n dp=[[INF]*n for _ in range(1<<n)];dp[1][0]=0\n for mask in range(1<<n):\n  for u in range(n):\n   if dp[mask][u]<INF:\n    for v in range(n):\n     if not (mask&(1<<v)): dp[mask|(1<<v)][v]=min(dp[mask|(1<<v)][v],dp[mask][u]+g[u][v])\n print(min(dp[(1<<n)-1][u]+g[u][0] for u in range(n)))", sample: [{ stdin: "4\n0 10 15 20 10 0 35 25 15 35 0 30 20 25 30 0", expectedOutput: "80" }], hidden: [{ stdin: "3\n0 1 2 1 0 3 2 3 0", expectedOutput: "6" }], complexity: "O(n^2 * 2^n)", conceptTags: ["bitmask-dp", "graphs"] },

  // Graphs & Trees (14)
  { title: "Connected Components in Undirected Graph", category: "graphs", difficulty: "Intermediate", statement: "Given V vertices (0..V-1), E edges, and E pairs of u v, print the number of connected components.", starterPy: "import sys\n", solPy: "import sys\nd=[int(x) for x in sys.stdin.read().split()]\nif d:\n v,e=d[0],d[1];p=list(range(v))\n def find(x):\n  while p[x]!=x: p[x]=p[p[x]];x=p[x]\n  return x\n for i in range(e):\n  u,w=find(d[2+2*i]),find(d[3+2*i])\n  if u!=w: p[u]=w\n print(len({find(i) for i in range(v)}))", sample: [{ stdin: "5 3\n0 1 1 2 3 4", expectedOutput: "2" }], hidden: [{ stdin: "4 0", expectedOutput: "4" }], complexity: "O(V + E)", conceptTags: ["union-find", "graphs"] },
  { title: "Shortest Path in Unweighted Graph (BFS)", category: "graphs", difficulty: "Intermediate", statement: "Given V, E, source S, target T, and E undirected edges, print shortest edge count from S to T or -1.", starterPy: "import sys\n", solPy: "import sys\nfrom collections import deque\nd=[int(x) for x in sys.stdin.read().split()]\nif d:\n v,e,s,t=d[0],d[1],d[2],d[3];g=[[] for _ in range(v)]\n for i in range(e):\n  u,w=d[4+2*i],d[5+2*i];g[u].append(w);g[w].append(u)\n dist=[-1]*v;dist[s]=0;q=deque([s])\n while q:\n  u=q.popleft()\n  for w in g[u]:\n   if dist[w]==-1: dist[w]=dist[u]+1;q.append(w)\n print(dist[t])", sample: [{ stdin: "4 4 0 3\n0 1 1 2 2 3 0 2", expectedOutput: "2" }], hidden: [{ stdin: "3 1 0 2\n0 1", expectedOutput: "-1" }], complexity: "O(V + E)", conceptTags: ["bfs", "graphs"] },
  { title: "Detect Cycle in Directed Graph", category: "graphs", difficulty: "Intermediate", statement: "Given V, E and E directed edges u -> v, print CYCLE if a directed cycle exists, else DAG.", starterPy: "import sys\n", solPy: "import sys\nfrom collections import deque\nd=[int(x) for x in sys.stdin.read().split()]\nif d:\n v,e=d[0],d[1];g=[[] for _ in range(v)];ind=[0]*v\n for i in range(e):\n  u,w=d[2+2*i],d[3+2*i];g[u].append(w);ind[w]+=1\n q=deque([i for i in range(v) if ind[i]==0]);cnt=0\n while q:\n  u=q.popleft();cnt+=1\n  for w in g[u]:\n   ind[w]-=1\n   if ind[w]==0: q.append(w)\n print('DAG' if cnt==v else 'CYCLE')", sample: [{ stdin: "2 2\n0 1 1 0", expectedOutput: "CYCLE" }], hidden: [{ stdin: "3 2\n0 1 1 2", expectedOutput: "DAG" }], complexity: "O(V + E)", conceptTags: ["topological-sort", "graphs"] },
  { title: "Bipartite Graph Check", category: "graphs", difficulty: "Intermediate", statement: "Given V, E and E undirected edges, print YES if the graph is bipartite, else NO.", starterPy: "import sys\n", solPy: "import sys\nfrom collections import deque\nd=[int(x) for x in sys.stdin.read().split()]\nif d:\n v,e=d[0],d[1];g=[[] for _ in range(v)]\n for i in range(e):\n  u,w=d[2+2*i],d[3+2*i];g[u].append(w);g[w].append(u)\n col=[0]*v;ok=True\n for i in range(v):\n  if not col[i]:\n   col[i]=1;q=deque([i])\n   while q:\n    u=q.popleft()\n    for w in g[u]:\n     if not col[w]: col[w]=-col[u];q.append(w)\n     elif col[w]==col[u]: ok=False\n print('YES' if ok else 'NO')", sample: [{ stdin: "4 4\n0 1 1 2 2 3 3 0", expectedOutput: "YES" }], hidden: [{ stdin: "3 3\n0 1 1 2 2 0", expectedOutput: "NO" }], complexity: "O(V + E)", conceptTags: ["bfs", "graphs"] },
  { title: "Dijkstra Shortest Weighted Path", category: "graphs", difficulty: "Advanced", statement: "Given V, E, source S, target T, and E triples (u, v, w), print shortest distance from S to T or -1.", starterPy: "import sys\n", solPy: "import sys,heapq\nd=[int(x) for x in sys.stdin.read().split()]\nif d:\n v,e,s,t=d[0],d[1],d[2],d[3];g=[[] for _ in range(v)]\n for i in range(e):\n  u,w,c=d[4+3*i],d[5+3*i],d[6+3*i];g[u].append((w,c))\n dist=[float('inf')]*v;dist[s]=0;pq=[(0,s)]\n while pq:\n  cd,u=heapq.heappop(pq)\n  if cd>dist[u]: continue\n  for w,c in g[u]:\n   if cd+c<dist[w]: dist[w]=cd+c;heapq.heappush(pq,(dist[w],w))\n print(dist[t] if dist[t]<float('inf') else -1)", sample: [{ stdin: "3 3 0 2\n0 1 4 0 2 10 1 2 2", expectedOutput: "6" }], hidden: [{ stdin: "2 0 0 1", expectedOutput: "-1" }], complexity: "O((V + E) log V)", conceptTags: ["dijkstra", "graphs"] },
  { title: "Minimum Spanning Tree Weight (Kruskal)", category: "graphs", difficulty: "Intermediate", statement: "Given V, E and E weighted undirected edges (u, v, w), print the total weight of the Minimum Spanning Tree.", starterPy: "import sys\n", solPy: "import sys\nd=[int(x) for x in sys.stdin.read().split()]\nif d:\n v,e=d[0],d[1];edges=sorted([(d[4+3*i],d[2+3*i],d[3+3*i]) for i in range(e)])\n p=list(range(v))\n def find(x):\n  while p[x]!=x: p[x]=p[p[x]];x=p[x]\n  return x\n ans=0\n for w,u,vv in edges:\n  ru,rv=find(u),find(vv)\n  if ru!=rv: p[ru]=rv;ans+=w\n print(ans)", sample: [{ stdin: "3 3\n0 1 1 1 2 2 0 2 5", expectedOutput: "3" }], hidden: [{ stdin: "2 1\n0 1 7", expectedOutput: "7" }], complexity: "O(E log E)", conceptTags: ["mst", "union-find", "graphs"] },
  { title: "Tree Diameter (Longest Path in Tree)", category: "graphs", difficulty: "Intermediate", statement: "Given N nodes (0..N-1) and N-1 edges of a tree, print its diameter (in edges).", starterPy: "import sys\n", solPy: "import sys\nfrom collections import deque\nd=[int(x) for x in sys.stdin.read().split()]\nif d:\n n=d[0]\n if n<=1: print(0)\n else:\n  g=[[] for _ in range(n)]\n  for i in range(n-1):\n   u,w=d[1+2*i],d[2+2*i];g[u].append(w);g[w].append(u)\n  def bfs(s):\n   dist=[-1]*n;dist[s]=0;q=deque([s]);far=s\n   while q:\n    u=q.popleft();far=u\n    for w in g[u]:\n     if dist[w]==-1: dist[w]=dist[u]+1;q.append(w)\n   return far,dist[far]\n  u,_=bfs(0);_,diam=bfs(u);print(diam)", sample: [{ stdin: "4\n0 1 1 2 1 3", expectedOutput: "2" }], hidden: [{ stdin: "2\n0 1", expectedOutput: "1" }], complexity: "O(N)", conceptTags: ["trees", "bfs", "graphs"] },
  { title: "Topological Sort Indegree Zero Count", category: "graphs", difficulty: "Introductory", statement: "Given V, E and E directed edges u -> v, print how many vertices initially have in-degree 0.", starterPy: "import sys\n", solPy: "import sys\nd=[int(x) for x in sys.stdin.read().split()]\nif d:\n v,e=d[0],d[1];ind=[0]*v\n for i in range(e): ind[d[3+2*i]]+=1\n print(ind.count(0))", sample: [{ stdin: "4 3\n0 1 0 2 1 3", expectedOutput: "1" }], hidden: [{ stdin: "3 1\n0 1", expectedOutput: "2" }], complexity: "O(V + E)", conceptTags: ["graphs", "topological-sort"] },
  { title: "Bellman-Ford Negative Cycle Detection", category: "graphs", difficulty: "Advanced", statement: "Given V, E and E directed weighted edges (u, v, w), print NEGATIVE_CYCLE if a negative weight cycle exists in the graph, else OK.", starterPy: "import sys\n", solPy: "import sys\nd=[int(x) for x in sys.stdin.read().split()]\nif d:\n v,e=d[0],d[1];edges=[(d[2+3*i],d[3+3*i],d[4+3*i]) for i in range(e)];dist=[0]*v;neg=False\n for it in range(v):\n  upd=False\n  for u,w,c in edges:\n   if dist[u]+c<dist[w]: dist[w]=dist[u]+c;upd=True\n  if it==v-1 and upd: neg=True\n print('NEGATIVE_CYCLE' if neg else 'OK')", sample: [{ stdin: "3 3\n0 1 1 1 2 -3 2 0 1", expectedOutput: "NEGATIVE_CYCLE" }], hidden: [{ stdin: "3 2\n0 1 2 1 2 -1", expectedOutput: "OK" }], complexity: "O(V * E)", conceptTags: ["bellman-ford", "graphs"] },
  { title: "Floyd-Warshall All-Pairs Shortest Path Sum", category: "graphs", difficulty: "Advanced", statement: "Given V, E and E directed edges (u, v, w), print the sum of shortest paths between all reachable pairs (u, v).", starterPy: "import sys\n", solPy: "import sys\nd=[int(x) for x in sys.stdin.read().split()]\nif d:\n v,e=d[0],d[1];INF=10**15;g=[[0 if i==j else INF for j in range(v)] for i in range(v)]\n for i in range(e):\n  u,w,c=d[2+3*i],d[3+3*i],d[4+3*i];g[u][w]=min(g[u][w],c)\n for k in range(v):\n  for i in range(v):\n   for j in range(v):\n    if g[i][k]+g[k][j]<g[i][j]: g[i][j]=g[i][k]+g[k][j]\n print(sum(g[i][j] for i in range(v) for j in range(v) if g[i][j]<INF))", sample: [{ stdin: "3 3\n0 1 2 1 2 3 0 2 10", expectedOutput: "10" }], hidden: [{ stdin: "2 1\n0 1 4", expectedOutput: "4" }], complexity: "O(V^3)", conceptTags: ["floyd-warshall", "graphs"] },
  { title: "Tarjan Bridges Count in Undirected Graph", category: "graphs", difficulty: "Advanced", statement: "Given V, E and E simple undirected edges, print the number of bridge edges whose removal increases connected components.", starterPy: "import sys\n", solPy: "import sys\nsys.setrecursionlimit(20000)\nd=[int(x) for x in sys.stdin.read().split()]\nif d:\n v,e=d[0],d[1];g=[[] for _ in range(v)]\n for i in range(e):\n  u,w=d[2+2*i],d[3+2*i];g[u].append(w);g[w].append(u)\n tin=[-1]*v;low=[-1]*v;timer=[0];ans=[0]\n def dfs(u,p):\n  tin[u]=low[u]=timer[0];timer[0]+=1\n  for w in g[u]:\n   if w==p: continue\n   if tin[w]!=-1: low[u]=min(low[u],tin[w])\n   else:\n    dfs(w,u);low[u]=min(low[u],low[w])\n    if low[w]>tin[u]: ans[0]+=1\n for i in range(v):\n  if tin[i]==-1: dfs(i,-1)\n print(ans[0])", sample: [{ stdin: "4 4\n0 1 1 2 2 0 1 3", expectedOutput: "1" }], hidden: [{ stdin: "3 2\n0 1 1 2", expectedOutput: "2" }], complexity: "O(V + E)", conceptTags: ["dfs", "bridges", "graphs"] },
  { title: "Maximum Bipartite Matching (Kuhns Algorithm)", category: "graphs", difficulty: "Advanced", statement: "Given L left nodes, R right nodes, E edges (u in 0..L-1, v in 0..R-1), print maximum bipartite matching size.", starterPy: "import sys\n", solPy: "import sys\nd=[int(x) for x in sys.stdin.read().split()]\nif d:\n L,R,e=d[0],d[1],d[2];g=[[] for _ in range(L)]\n for i in range(e): g[d[3+2*i]].append(d[4+2*i])\n mt=[-1]*R\n def dfs(u,vis):\n  for v in g[u]:\n   if not vis[v]:\n    vis[v]=True\n    if mt[v]==-1 or dfs(mt[v],vis): mt[v]=u;return True\n  return False\n print(sum(1 for i in range(L) if dfs(i,[False]*R)))", sample: [{ stdin: "3 3 4\n0 0 0 1 1 1 2 2", expectedOutput: "3" }], hidden: [{ stdin: "2 2 2\n0 0 1 0", expectedOutput: "1" }], complexity: "O(V * E)", conceptTags: ["bipartite-matching", "graphs"] },
  { title: "Lowest Common Ancestor in Rooted Tree (Root 0)", category: "graphs", difficulty: "Advanced", statement: "Given N nodes (root 0), two query nodes A and B, and N-1 parent-child directed edges u -> v, print the LCA of A and B.", starterPy: "import sys\n", solPy: "import sys\nd=[int(x) for x in sys.stdin.read().split()]\nif d:\n n,a,b=d[0],d[1],d[2];par={0:-1}\n for i in range(n-1): par[d[4+2*i]]=d[3+2*i]\n anc=set();cur=a\n while cur!=-1: anc.add(cur);cur=par.get(cur,-1)\n cur=b\n while cur not in anc: cur=par.get(cur,-1)\n print(cur)", sample: [{ stdin: "5 3 4\n0 1 1 2 1 3 0 4", expectedOutput: "0" }], hidden: [{ stdin: "4 2 3\n0 1 1 2 1 3", expectedOutput: "1" }], complexity: "O(N)", conceptTags: ["trees", "lca", "graphs"] },
  { title: "Edmonds-Karp Maximum S-T Flow", category: "graphs", difficulty: "Advanced", statement: "Given V, E, source S, sink T, and E directed edges (u, v, cap), print the maximum flow from S to T.", starterPy: "import sys\n", solPy: "import sys\nfrom collections import deque\nd=[int(x) for x in sys.stdin.read().split()]\nif d:\n v,e,s,t=d[0],d[1],d[2],d[3];cap=[[0]*v for _ in range(v)]\n for i in range(e): cap[d[4+3*i]][d[5+3*i]]+=d[6+3*i]\n flow=0\n while True:\n  par=[-1]*v;par[s]=s;q=deque([(s,10**15)])\n  pushed=0\n  while q:\n   u,f=q.popleft()\n   if u==t: pushed=f;break\n   for w in range(v):\n    if par[w]==-1 and cap[u][w]>0: par[w]=u;q.append((w,min(f,cap[u][w])))\n  if not pushed: break\n  flow+=pushed;cur=t\n  while cur!=s: p=par[cur];cap[p][cur]-=pushed;cap[cur][p]+=pushed;cur=p\n print(flow)", sample: [{ stdin: "4 5 0 3\n0 1 10 0 2 10 1 2 2 1 3 8 2 3 10", expectedOutput: "18" }], hidden: [{ stdin: "2 1 0 1\n0 1 7", expectedOutput: "7" }], complexity: "O(V * E^2)", conceptTags: ["max-flow", "bfs", "graphs"] }
];

const rows = [];
let idx = 1;

for (const p of baseProblems) {
  rows.push({
    id: `c${String(idx++).padStart(3, "0")}`,
    title: p.title,
    category: p.category,
    questionSubType: "coding_problem",
    language: "python",
    difficulty: p.difficulty,
    statement: p.statement,
    constraints: "1 <= N <= 10^5, time limit 2.0s",
    starterCode: p.starterPy,
    referenceSolution: p.solPy,
    sampleTests: p.sample,
    hiddenTests: p.hidden,
    expectedTimeComplexity: p.complexity,
    conceptTags: p.conceptTags || [p.category],
    needsReview: false
  });
}

